# traversal shape degree among 2 nodes
from collections import deque,Counter
pts={(r,c) for r,row in enumerate(D1out) for c,v in enumerate(row) if v==2}; q=deque([next(iter(pts))]); seen={q[0]}
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if p in pts and p not in seen:seen.add(p);q.append(p)
deg=Counter(sum((r+dr,c+dc) in pts for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))) for r,c in pts)
print('pts',len(pts),'components',len(seen),'degrees',deg,'endpoints',sorted(p for p in pts if sum((p[0]+dr,p[1]+dc) in pts for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))==1))
print('branch',sorted(p for p in pts if sum((p[0]+dr,p[1]+dc) in pts for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))>2))

